            <circle id="pointDot" class="point-dot" cx="650" cy="330" r="7"></circle>
            <text id="pointLabel" class="point-label" x="662" y="318">P</text>
            <text id="projYLabel" class="proj-label" x="397" y="322"></text>
            <circle id="pointHit" class="point-hit" cx="650" cy="330" r="24"></circle>
          </g>

          <text class="plot-note" x="100" y="592">纵轴压缩显示：x、y 轴单位长度不同；曲线按函数式计算</text>
        </svg>
      </div>

      <div class="control-deck">
