        </div>

        <div class="slider-group is-hidden" id="yControl">
          <div class="control-head">
            <label for="ySlider">扫描高度 <span class="math-chip">y</span></label>
            <span class="control-hint">演示区间 −30 到 −8</span>
          </div>
          <input id="ySlider" type="range" min="-30" max="-8" step="0.1" value="-20" aria-label="扫描高度 y">
