        <button type="button" class="primary" id="nextBtn">下一步</button>
      </div>

      <section class="panel answer-panel is-hidden" id="answerPanel">
        <div class="answer-kicker">值域的完整写法</div>
        <div class="answer-value">(−∞, −13]</div>
        <div class="answer-note">最大值 −13 在 x = 1 取得；向下没有最小值。</div>
      </section>
    </aside>
  </main>

  <footer class="footnote">
    主图显示范围为 x ∈ [−3.2, 5.2]，y ∈ [−32, 2]，且纵轴经过压缩；函数本身对所有实数 x 都有定义。扫描高度只演示 −30 到 −8 这一段，抛物线还会继续向下无限延伸。
  </footer>
</div>

<script>
  const NS = "http://www.w3.org/2000/svg";
  const XMIN = -3.2, XMAX = 5.2, YMIN = -32, YMAX = 2;
  const L = 90, R = 870, T = 55, B = 555;
  const VX = 1, VY = -13;

  const sx = x => L + (x - XMIN) / (XMAX - XMIN) * (R - L);
  const sy = y => T + (YMAX - y) / (YMAX - YMIN) * (B - T);
  const f = x => -x * x + 2 * x - 14;

  const $ = id => document.getElementById(id);
  const svg = $("board");

  let state = 1;
  let currentX = 3;
  let scanY = -20;
  let playing = false;
  let raf = null;
  let animDir = 1;
  let dwell = 0;
  let draggingPoint = false;

  function fmt(n, d = 2) {
    const eps = 0.5 * Math.pow(10, -d);
    if (Math.abs(n) < eps) n = 0;
    const v = Math.abs(n).toFixed(d);
    return (n < 0 ? "−" : "") + v;
  }

  function setAttrs(el, attrs) {
    for (const key in attrs) el.setAttribute(key, attrs[key]);
  }

  function svgNode(tag, attrs = {}, text = null) {
    const node = document.createElementNS(NS, tag);
    setAttrs(node, attrs);
    if (text !== null) node.textContent = text;
    return node;
  }

  function addTo(parent, tag, attrs = {}, text = null) {
    const node = svgNode(tag, attrs, text);
    parent.appendChild(node);
    return node;
  }

  function drawStatic() {
    let d = "";
    const step = 0.02;
    for (let x = XMIN; x <= XMAX + 1e-9; x += step) {
      const px = sx(x);
      const py = sy(f(x));
      d += (d === "" ? "M" : " L") + px.toFixed(2) + " " + py.toFixed(2);
    }
    $("curvePath").setAttribute("d", d);
    $("curveHalo").setAttribute("d", d);

    const vx = sx(VX);
    const vy = sy(VY);

    setAttrs($("ceilingLine"), { x1: L, y1: vy, x2: R, y2: vy });
    setAttrs($("ceilingLabel"), { x: R - 12, y: vy - 13 });

    setAttrs($("rangeLine"), { x1: 910, y1: vy, x2: 910, y2: B - 12 });
    setAttrs($("rangeTopTick"), { x1: 897, y1: vy, x2: 923, y2: vy });
    setAttrs($("rangeDot"), { cx: 910, cy: vy });
    setAttrs($("rangeTitle"), { x: 910, y: vy - 24 });
    setAttrs($("rangeTopLabel"), { x: 927, y: vy + 5 });
    setAttrs($("rangeBottomLabel"), { x: 927, y: B - 14 });

    setAttrs($("symAxis"), { x1: vx, y1: T, x2: vx, y2: B });
    setAttrs($("vertexDot"), { cx: vx, cy: vy });
    setAttrs($("vertexLabel"), { x: vx + 14, y: vy - 13 });
    setAttrs($("symLabel"), { x: vx + 8, y: T + 25 });

    const grid = $("gridLayer");
    grid.innerHTML = "";

    for (let x = -3; x <= 5; x++) {
      addTo(grid, "line", {
        x1: sx(x), y1: T, x2: sx(x), y2: B, class: "grid-line"
      });
    }

    for (let y = -30; y <= 0; y += 5) {
      addTo(grid, "line", {
        x1: L, y1: sy(y), x2: R, y2: sy(y), class: "grid-line"
      });
    }

    const axis = $("axisLayer");
    axis.innerHTML = "";

    addTo(axis, "line", {
      x1: L, y1: sy(0), x2: R + 9, y2: sy(0),
      class: "axis-line", "marker-end": "url(#arrowAxis)"
    });

    addTo(axis, "line", {
      x1: sx(0), y1: B, x2: sx(0), y2: T - 9,
      class: "axis-line", "marker-end": "url(#arrowAxis)"
    });

    addTo(axis, "text", {
      x: R + 19, y: sy(0) + 6, class: "axis-name"
    }, "x");

    addTo(axis, "text", {
      x: sx(0) + 12, y: T - 8, class: "axis-name"
    }, "y");

    for (let x = -3; x <= 5; x++) {
      addTo(axis, "text", {
        x: sx(x), y: sy(0) + 24, class: "tick-label", "text-anchor": "middle"
      }, x === 0 ? "0" : fmt(x, 0));
    }

    for (let y = -5; y >= -30; y -= 5) {
      addTo(axis, "text", {
        x: sx(0) - 10, y: sy(y) + 5, class: "tick-label", "text-anchor": "end"
      }, fmt(y, 0));
    }
  }

  const stateData = [
    {
      graphTitle: "曲线上点 P 的高度",
      stage: "观察",
      explainTitle: "先看函数值怎样出现",
      body: `<p>红点 P 在曲线上，它的纵坐标就是函数值 <b>y</b>。拖动 x 滑块，或直接拖动 P。</p>
        <div class="cue">看 P 的高度怎样随横坐标 x 改变。</div>`,
      formula: `<div class="calc-line">原函数：<span class="eq-main">y = −x<sup>2</sup> + 2x − 14</span></div>
        <div class="formula-note">P 的坐标写作 (x, y)，其中 y = f(x)。</div>`
    },
    {
      graphTitle: "配方后看见顶点",
      stage: "顶点式",
      explainTitle: "把平方项和高度差连起来",
      body: `<p>配方不改变函数，只换一种写法：<b>y = −(x−1)<sup>2</sup> − 13</b>。</p>
        <div class="cue">绿色竖段表示 P 比顶点低 (x−1)<sup>2</sup>；横坐标离 1 越远，P 就越低。</div>`,
      formula: `<div class="calc-line">y = −x<sup>2</sup> + 2x − 14</div>
        <div class="calc-line">　= −(x<sup>2</sup> − 2x) − 14</div>
        <div class="calc-line">　= −[(x − 1)<sup>2</sup> − 1] − 14</div>
        <div class="calc-line strong-line">　= −(x − 1)<sup>2</sup> − 13</div>
        <div class="formula-note">顶点： (1, −13)</div>`
    },
    {
      graphTitle: "高度上限 −13",
      stage: "上界",
      explainTitle: "平方项把高度往下拉",
      body: `<p>平方项 <b>(x−1)<sup>2</sup></b> 最小为 0；前面的负号使它只能把高度往下拉。</p>
        <div class="cue">所以 y 不可能高于 −13；当 x = 1 时正好到达 −13。</div>`,
      formula: `<div class="calc-line">(x − 1)<sup>2</sup> ≥ 0</div>
        <div class="calc-line">⇒ −(x − 1)<sup>2</sup> ≤ 0</div>
        <div class="calc-line strong-line">⇒ y = −(x − 1)<sup>2</sup> − 13 ≤ −13</div>
        <div class="formula-note">等号在 x = 1 时取得。</div>`
    },
    {
      graphTitle: "扫描所有高度",
      stage: "完整值域",
      explainTitle: "哪些 y 能找到交点？",
      body: `<p>紫色水平线表示某个高度 y。拖动扫描：低于 −13 有两个交点；等于 −13 只有一个；高于 −13 没有交点。</p>
        <div class="cue">因此所有 y ≤ −13 都能取到，且只有这些高度能取到。</div>`,
      formula: `<div class="calc-line">y = −(x − 1)<sup>2</sup> − 13</div>
        <div class="calc-line">(x − 1)<sup>2</sup> = −13 − y</div>
        <div class="calc-line strong-line">x = 1 ± √(−13 − y)</div>
        <div class="formula-note">当且仅当 −13 − y ≥ 0，即 y ≤ −13，方程才有实数解。</div>`
    }
  ];

  function renderGraph() {
    const scanState = state === 4;

    $("pointLayer").classList.toggle("is-hidden", scanState);
    $("scanLayer").classList.toggle("is-hidden", !scanState);
    $("vertexLayer").classList.toggle("is-hidden", state < 2);
    $("ceilingLayer").classList.toggle("is-hidden", state < 3);
    $("rangeLayer").classList.toggle("is-hidden", state < 4);
    $("dropLayer").classList.toggle("is-hidden", !(state >= 2 && state <= 3));

    $("xSlider").value = currentX;
    $("ySlider").value = scanY;

    if (!scanState) {
      const yv = f(currentX);
      const px = sx(currentX);
      const py = sy(yv);
      const axisX = sx(0);
      const axisY0 = sy(0);
      const drop = (currentX - 1) * (currentX - 1);

      setAttrs($("projH"), { x1: px, y1: py, x2: axisX, y2: py });
      setAttrs($("projV"), { x1: px, y1: py, x2: px, y2: axisY0 });
      setAttrs($("axisDot"), { cx: axisX, cy: py });
      setAttrs($("xAxisDot"), { cx: px, cy: axisY0 });
      setAttrs($("pointRing"), { cx: px, cy: py });
      setAttrs($("pointDot"), { cx: px, cy: py });
      setAttrs($("pointHit"), { cx: px, cy: py });

      const nearVertex = Math.abs(currentX - 1) < 0.06;
      let anchor = currentX > 4.5 ? "end" : "start";
      let dx = anchor === "end" ? -12 : 12;
      let dy = state >= 2 ? 30 : -12;
      if (nearVertex && state >= 2) dy = 34;

      setAttrs($("pointLabel"), {
        x: px + dx,
        y: py + dy,
        "text-anchor": anchor
      });
      $("pointLabel").textContent = nearVertex && state >= 2 ? "P = 顶点" : "P";

      setAttrs($("projYLabel"), {
        x: axisX + 10,
        y: py - 8,
        "text-anchor": "start"
      });
      $("projYLabel").textContent = "y = " + fmt(yv, 2);

      if (state >= 2 && state <= 3) {
        const vx = sx(VX);
        const vy = sy(VY);
        setAttrs($("dropH"), { x1: vx, y1: vy, x2: px, y2: vy });
        setAttrs($("dropV"), { x1: px, y1: vy, x2: px, y2: py });

        let labelX = px + 10;
        let labelAnchor = "start";
        if (currentX > 4.35) {
          labelX = px - 10;
          labelAnchor = "end";
        }
        let labelY = (vy + py) / 2 + 4;
        if (drop < 0.04) {
          labelX = vx + 14;
          labelAnchor = "start";
          labelY = vy + 26;
        }

        setAttrs($("dropLabel"), {
          x: labelX,
          y: labelY,
          "text-anchor": labelAnchor
        });
        $("dropLabel").textContent = "(x−1)² = " + fmt(drop, 2);
      }

      if (state === 1) {
        $("xReadout").innerHTML = `x = ${fmt(currentX, 2)}　y = ${fmt(yv, 2)}`;
      } else {
        $("xReadout").innerHTML =
          `x = ${fmt(currentX, 2)}　y = ${fmt(yv, 2)}　(x−1)<sup>2</sup> = ${fmt(drop, 2)}`;
      }
    } else {
      const lineY = sy(scanY);
      const delta = -13 - scanY;
      const s = Math.sqrt(Math.max(0, delta));
      const leftX = sx(1 - s);
      const rightX = sx(1 + s);

      setAttrs($("scanLine"), { x1: L, y1: lineY, x2: R, y2: lineY });
      setAttrs($("scanLabel"), { x: L + 12, y: lineY - 10, "text-anchor": "start" });
      $("scanLabel").textContent = "y = " + fmt(scanY, 1);

      const noRoot = scanY > -13 + 1e-9;
      const tangent = !noRoot && delta < 0.01;

      $("scanDotR").style.display = tangent || noRoot ? "none" : "";
      $("scanRootR").style.display = tangent || noRoot ? "none" : "";

      if (noRoot) {
        $("scanDotL").style.display = "none";
        $("scanRootL").style.display = "none";
        $("scanNoInt").style.display = "";
        setAttrs($("scanNoInt"), {
          x: sx(1),
          y: lineY - 16,
          "text-anchor": "middle"
        });
        $("scanNoInt").textContent = "无实数交点：y 高于 −13";
        $("yReadout").innerHTML =
          `y = ${fmt(scanY, 1)}：方程无实数解（y 高于 −13）`;
      } else if (tangent) {
        $("scanDotL").style.display = "";
        setAttrs($("scanDotL"), { cx: sx(1), cy: lineY });
        $("scanRootL").style.display = "";
        setAttrs($("scanRootL"), {
          x: sx(1) + 16,
          y: lineY + 22,
          "text-anchor": "start"
        });
        $("scanRootL").textContent = "x = 1（顶点）";
        $("scanNoInt").style.display = "none";
        $("yReadout").innerHTML =
          `y = −13：水平线与抛物线相切于顶点，x = 1`;
      } else {
        $("scanDotL").style.display = "";
        setAttrs($("scanDotL"), { cx: leftX, cy: lineY });
        setAttrs($("scanDotR"), { cx: rightX, cy: lineY });

        let leftAnchor = "middle";
        let leftLabelX = leftX;
        if (leftX < L + 58) {
          leftAnchor = "start";
          leftLabelX = leftX + 10;
        }

        let rightAnchor = "middle";
        let rightLabelX = rightX;
        if (rightX > R - 58) {
          rightAnchor = "end";
          rightLabelX = rightX - 10;
        }

        $("scanRootL").style.display = "";
        setAttrs($("scanRootL"), {
          x: leftLabelX,
          y: lineY + 22,
          "text-anchor": leftAnchor
        });
        $("scanRootL").textContent = "x1 = " + fmt(1 - s, 2);

        $("scanRootR").style.display = "";
        setAttrs($("scanRootR"), {
          x: rightLabelX,
          y: lineY + 22,
          "text-anchor": rightAnchor
        });
        $("scanRootR").textContent = "x2 = " + fmt(1 + s, 2);

        $("scanNoInt").style.display = "none";
        $("yReadout").innerHTML =
          `y = ${fmt(scanY, 1)}：交点 x<sub>1</sub> = ${fmt(1 - s, 2)}，x<sub>2</sub> = ${fmt(1 + s, 2)}`;
      }
    }
  }

  function renderAll() {
    const data = stateData[state - 1];

    $("stateTitle").textContent = data.graphTitle;
    $("stepLabel").textContent = `步骤 ${state} / 4 · ${data.stage}`;
    $("explainTitle").textContent = data.explainTitle;
    $("explainBody").innerHTML = data.body;
    $("formulaBox").innerHTML = data.formula;

    $("answerPanel").classList.toggle("is-hidden", state !== 4);
    $("prevBtn").disabled = state === 1;
    $("nextBtn").disabled = state === 4;
    $("testBtn").classList.toggle("is-hidden", state !== 4);

    if (state === 4) {
      $("keyBtn").textContent = "扫到 −13";
    } else if (state === 1) {
      $("keyBtn").textContent = "到最高处";
    } else {
      $("keyBtn").textContent = "到顶点";
    }

    document.querySelectorAll(".step-pill").forEach(btn => {
      btn.classList.toggle("active", Number(btn.dataset.state) === state);
    });

    $("xControl").classList.toggle("is-hidden", state === 4);
    $("yControl").classList.toggle("is-hidden", state !== 4);

    renderGraph();
  }

  function stopPlay() {
    playing = false;
    if (raf) {
      cancelAnimationFrame(raf);
      raf = null;
    }
    $("playBtn").textContent = "播放";
  }

  function startPlay() {
    if (playing) return;
    playing = true;
    dwell = 0;
    $("playBtn").textContent = "暂停";

    if (state === 4) {
      animDir = scanY < -13 ? 1 : -1;
    } else {
      animDir = currentX > 1 ? -1 : 1;
    }

    let last = performance.now();

    function frame(ts) {
      if (!playing) return;
      const dt = Math.min(50, ts - last) / 1000;
      last = ts;

      if (dwell > 0) {
        dwell -= dt;
      } else if (state === 4) {
        const prev = scanY;
        scanY += animDir * 4.2 * dt;

        if (prev < -13 && scanY >= -13 && animDir > 0) {
          scanY = -13;
          dwell = 0.38;
        } else if (prev > -13 && scanY <= -13 && animDir < 0) {
          scanY = -13;
          dwell = 0.38;
        }

        if (scanY >= -8) {
          scanY = -8;
          animDir = -1;
          dwell = 0.18;
        } else if (scanY <= -30) {
          scanY = -30;
          animDir = 1;
          dwell = 0.18;
        }
      } else {
        currentX += animDir * 1.9 * dt;
        if (currentX >= XMAX) {
          currentX = XMAX;
          animDir = -1;
          dwell = 0.16;
        } else if (currentX <= XMIN) {
          currentX = XMIN;
          animDir = 1;
          dwell = 0.16;
        }
      }

      renderGraph();
      raf = requestAnimationFrame(frame);
    }

    raf = requestAnimationFrame(frame);
  }

  function setState(n) {
    if (n < 1 || n > 4) return;
    stopPlay();
    state = n;
    renderAll();
  }

  function clientToSvgPoint(evt) {
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  function movePointFromClient(evt) {
    if (state === 4) return;
    const p = clientToSvgPoint(evt);
    let x = XMIN + (p.x - L) / (R - L) * (XMAX - XMIN);
    x = Math.max(XMIN, Math.min(XMAX, x));
    currentX = Math.round(x * 100) / 100;
    renderGraph();
  }

  document.querySelectorAll(".step-pill").forEach(btn => {
    btn.addEventListener("click", () => setState(Number(btn.dataset.state)));
  });

  $("prevBtn").addEventListener("click", () => setState(state - 1));
  $("nextBtn").addEventListener("click", () => setState(state + 1));

  $("xSlider").addEventListener("input", e => {
    stopPlay();
    currentX = parseFloat(e.target.value);
    renderGraph();
  });

  $("ySlider").addEventListener("input", e => {
    stopPlay();
    scanY = parseFloat(e.target.value);
    renderGraph();
  });

  $("playBtn").addEventListener("click", () => {
    if (playing) {
      stopPlay();
    } else {
      startPlay();
    }
  });

  $("keyBtn").addEventListener("click", () => {
    stopPlay();
    if (state === 4) {
      scanY = -13;
    } else {
      currentX = 1;
    }
    renderGraph();
  });

  $("testBtn").addEventListener("click", () => {
    stopPlay();
    scanY = -10;
    renderGraph();
  });

  $("resetBtn").addEventListener("click", () => {
    stopPlay();
    state = 1;
    currentX = 3;
    scanY = -20;
    renderAll();
  });

  $("pointHit").addEventListener("pointerdown", e => {
    if (state === 4) return;
    stopPlay();
    draggingPoint = true;
    e.target.setPointerCapture(e.pointerId);
    movePointFromClient(e);
    e.preventDefault();
  });

  $("pointHit").addEventListener("pointermove", e => {
    if (!draggingPoint) return;
    movePointFromClient(e);
    e.preventDefault();
  });

  function endPointDrag(e) {
    draggingPoint = false;
    if (e.target.hasPointerCapture && e.target.hasPointerCapture(e.pointerId)) {
      e.target.releasePointerCapture(e.pointerId);
    }
  }

  $("pointHit").addEventListener("pointerup", endPointDrag);
  $("pointHit").addEventListener("pointercancel", endPointDrag);

  drawStatic();
  setState(1);
</script>
</body>
</html>
